# New pure validator/id helper
p=root/'app/src/main/java/com/fer/bandlab/device/WatchfaceFile.kt'
p.write_text('''package com.fer.bandlab.device\n\nimport java.security.MessageDigest\n\n/** Pure validation/id helper. It intentionally does not claim model compatibility. */\nobject WatchfaceFile {\n    const val MIN_BYTES = 512\n    const val MAX_BYTES = 16 * 1024 * 1024\n\n    fun validateSize(bytes: ByteArray) {\n        require(bytes.size >= MIN_BYTES) { "El archivo es demasiado pequeño para ser una esfera" }\n        require(bytes.size <= MAX_BYTES) { "El archivo supera el límite seguro de 16 MB" }\n    }\n\n    fun stableId(bytes: ByteArray): String {\n        validateSize(bytes)\n        val hash = MessageDigest.getInstance("SHA-256").digest(bytes)\n            .joinToString("") { "%02x".format(it) }\n        return "bandlab_${hash.take(16)}"\n    }\n}\n''')

# WatchfaceTransport
