s=s.replace('''            require(bytes.size >= 512) { "El archivo es demasiado pequeño para ser una esfera" }\n            val current = manager.listWatchfaces().firstOrNull { it.active }\n            if (current != null) prefs.setPreviousFace(current.id, current.name)\n            val id = "bandlab_${sha256(bytes).take(16)}"\n            manager.installWatchface(bytes, id, onProgress)\n            prefs.setLastBandLabFace(id)\n            Result.Success("Esfera instalada y activada · ${bytes.size / 1024} KB")\n''','''            WatchfaceFile.validateSize(bytes)\n            val current = manager.listWatchfaces().firstOrNull { it.active }\n            if (current != null) prefs.setPreviousFace(current.id, current.name)\n            val id = WatchfaceFile.stableId(bytes)\n            val installed = manager.installWatchface(bytes, id, onProgress)\n            prefs.setLastBandLabFace(id)\n            Result.Success("Esfera activa: ${installed.name.ifBlank { installed.id }} · ${bytes.size / 1024} KB")\n''')
s=s.replace('''\n    private fun sha256(bytes: ByteArray): String = MessageDigest.getInstance("SHA-256")\n        .digest(bytes).joinToString("") { "%02x".format(it) }\n''','\n')
