# Manager replace watchface block functions
p=root/'app/src/main/java/com/fer/bandlab/device/XiaomiBandManager.kt'
s=p.read_text()
start=s.index('    data class WatchfaceInfo(')
end=s.index('    private fun requireReady()', start)
new='''    data class WatchfaceInfo(\n        val id: String,\n        val name: String,\n        val active: Boolean,\n        val canDelete: Boolean,\n    )\n\n    suspend fun listWatchfaces(): List<WatchfaceInfo> {\n        val drv = driver ?: throw IllegalStateException("Band no conectada")\n        requireReady()\n        drv.sendCommand(\n            XiaomiProto.Command.newBuilder()\n                .setType(4).setSubtype(0).build()\n        )\n        val reply = withTimeoutOrNull(8_000) {\n            drv.incoming.first { it.type == 4 && it.subtype == 0 }\n        } ?: throw IllegalStateException("La Band no respondió a la lista de esferas")\n        val list = reply.command.watchface.watchfaceList\n        val faces = (0 until list.watchfaceCount).map { i ->\n            val w = list.getWatchface(i)\n            WatchfaceInfo(w.id, w.name, w.active, w.canDelete)\n        }\n        log("watchface-list", true, "count=${faces.size} active=${faces.firstOrNull { it.active }?.id}")\n        return faces\n    }\n\n    suspend fun installWatchface(\n        bytes: ByteArray,\n        watchfaceId: String,\n        onProgress: (Int) -> Unit = {},\n    ): WatchfaceInfo {\n        val drv = driver ?: throw IllegalStateException("Band no conectada")\n        requireReady()\n        WatchfaceFile.validateSize(bytes)\n        onProgress(0)\n        drv.sendCommand(\n            XiaomiProto.Command.newBuilder()\n                .setType(4).setSubtype(4)\n                .setWatchface(\n                    XiaomiProto.Watchface.newBuilder().setWatchfaceInstallStart(\n                        XiaomiProto.WatchfaceInstallStart.newBuilder()\n                            .setId(watchfaceId).setSize(bytes.size)\n                    )\n                ).build()\n        )\n        val accepted = withTimeoutOrNull(10_000) {\n            drv.incoming.first { it.type == 4 && it.subtype == 4 }\n        } ?: throw IllegalStateException("Timeout esperando autorización de instalación")\n        val status = accepted.command.watchface.installStatus\n        when (status) {\n            0 -> {\n                val ok = MiBand9DataUploader.upload(drv, MiBand9DataUploader.TYPE_WATCHFACE, bytes, onProgress)\n                if (!ok) throw IllegalStateException("Falló la transferencia de la esfera")\n            }\n            2 -> {\n                onProgress(100)\n                log("watchface-upload", true, "already-installed id=$watchfaceId")\n            }\n            else -> throw IllegalStateException("La Band rechazó la esfera (status=$status)")\n        }\n        val active = setActiveWatchface(watchfaceId)\n        log("watchface", true, "installed/selected id=$watchfaceId bytes=${bytes.size} status=$status")\n        return active\n    }\n\n    suspend fun setActiveWatchface(id: String): WatchfaceInfo {\n        val drv = driver ?: throw IllegalStateException("Band no conectada")\n        requireReady()\n        drv.sendCommand(\n            XiaomiProto.Command.newBuilder().setType(4).setSubtype(1)\n                .setWatchface(XiaomiProto.Watchface.newBuilder().setWatchfaceId(id)).build()\n        )\n        repeat(4) { attempt ->\n            delay(350L + attempt * 250L)\n            val faces = runCatching { listWatchfaces() }.getOrNull().orEmpty()\n            faces.firstOrNull { it.id == id && it.active }?.let {\n                log("watchface-activate", true, "verified id=$id attempt=${attempt + 1}")\n                return it\n            }\n        }\n        log("watchface-activate", false, "not verified id=$id")\n        throw IllegalStateException("La Band recibió la activación, pero no confirmó la esfera como activa")\n    }\n\n    suspend fun deleteWatchface(id: String) {\n        val drv = driver ?: throw IllegalStateException("Band no conectada")\n        requireReady()\n        val current = listWatchfaces().firstOrNull { it.id == id }\n            ?: return\n        require(!current.active) { "No se puede borrar la esfera que está activa" }\n        require(current.canDelete) { "Xiaomi marca esta esfera como no eliminable" }\n        drv.sendCommand(\n            XiaomiProto.Command.newBuilder().setType(4).setSubtype(2)\n                .setWatchface(XiaomiProto.Watchface.newBuilder().setWatchfaceId(id)).build()\n        )\n        repeat(4) { attempt ->\n            delay(350L + attempt * 250L)\n            val faces = runCatching { listWatchfaces() }.getOrNull() ?: return@repeat\n            if (faces.none { it.id == id }) {\n                log("watchface-delete", true, "verified id=$id attempt=${attempt + 1}")\n                return\n            }\n        }\n        log("watchface-delete", false, "not verified id=$id")\n        throw IllegalStateException("La Band recibió el borrado, pero la esfera sigue apareciendo")\n    }\n\n'''
s=s[:start]+new+s[end:]
p.write_text(s)

