new='''    private fun mapWatchfaces(faces: List<XiaomiBandManager.WatchfaceInfo>): List<WatchfaceUiItem> =\n        faces.map { WatchfaceUiItem(it.id, it.name, it.active, it.canDelete) }\n\n    private fun setWatchfaceSnapshot(\n        faces: List<XiaomiBandManager.WatchfaceInfo>,\n        status: String,\n        loading: Boolean = false,\n        installing: Boolean = false,\n        progress: Int? = null,\n    ) {\n        _watchfaces.value = WatchfaceUiState(\n            loading = loading,\n            installing = installing,\n            progressPercent = progress,\n            faces = mapWatchfaces(faces),\n            previousFaceId = prefs.getPreviousFaceId(),\n            previousFaceName = prefs.getPreviousFaceName(),\n            statusText = status,\n        )\n    }\n\n    fun refreshWatchfaces() {\n        viewModelScope.launch {\n            if (deviceState.value.status != com.fer.bandlab.model.BandConnectionStatus.READY) {\n                _watchfaces.value = _watchfaces.value.copy(loading = false, statusText = "Conectá la Band para leer sus esferas")\n                return@launch\n            }\n            _watchfaces.value = _watchfaces.value.copy(loading = true, statusText = "Leyendo esferas desde la Band…")\n            runCatching { bandManager.listWatchfaces() }\n                .onSuccess { faces -> setWatchfaceSnapshot(faces, if (faces.isEmpty()) "La Band respondió sin esferas" else "${faces.size} esfera(s) leídas desde Xiaomi") }\n                .onFailure { _watchfaces.value = _watchfaces.value.copy(loading = false, statusText = it.message ?: "No pude leer las esferas") }\n        }\n    }\n\n    fun installWatchfaceBin(uri: Uri) {\n        viewModelScope.launch {\n            _watchfaces.value = _watchfaces.value.copy(installing = true, progressPercent = 0, statusText = "Preparando esfera .bin…")\n            val r = watchfaceTransport.importAndInstallBin(uri, deviceState.value) { progress ->\n                _watchfaces.value = _watchfaces.value.copy(installing = true, progressPercent = progress.coerceIn(0, 100), statusText = "Transfiriendo esfera… ${progress.coerceIn(0, 100)}%")\n            }\n            val m = when (r) {\n                is WatchfaceTransport.Result.Success -> r.message\n                is WatchfaceTransport.Result.NotReady -> r.message\n                is WatchfaceTransport.Result.Failure -> r.message\n            }\n            val faces = if (r is WatchfaceTransport.Result.Success) runCatching { bandManager.listWatchfaces() }.getOrDefault(emptyList()) else emptyList()\n            if (faces.isNotEmpty()) setWatchfaceSnapshot(faces, m, installing = false, progress = null)\n            else _watchfaces.value = _watchfaces.value.copy(installing = false, progressPercent = null, statusText = m)\n            _snackbar.value = m\n        }\n    }\n\n    fun activateWatchface(id: String) {\n        viewModelScope.launch {\n            _watchfaces.value = _watchfaces.value.copy(loading = true, statusText = "Activando esfera…")\n            runCatching { bandManager.setActiveWatchface(id) }\n                .onSuccess {\n                    val faces = runCatching { bandManager.listWatchfaces() }.getOrDefault(emptyList())\n                    setWatchfaceSnapshot(faces, "Esfera activada y confirmada por la Band")\n                    _snackbar.value = "Esfera activada"\n                }\n                .onFailure {\n                    _watchfaces.value = _watchfaces.value.copy(loading = false, statusText = it.message ?: "No pude activar la esfera")\n                    _snackbar.value = it.message ?: "No pude activar la esfera"\n                }\n        }\n    }\n\n    fun deleteWatchface(id: String) {\n        viewModelScope.launch {\n            _watchfaces.value = _watchfaces.value.copy(loading = true, statusText = "Eliminando esfera…")\n            runCatching { bandManager.deleteWatchface(id) }\n                .onSuccess {\n                    val faces = runCatching { bandManager.listWatchfaces() }.getOrDefault(emptyList())\n                    setWatchfaceSnapshot(faces, "Esfera eliminada y lista actualizada")\n                    _snackbar.value = "Esfera eliminada"\n                }\n                .onFailure {\n                    _watchfaces.value = _watchfaces.value.copy(loading = false, statusText = it.message ?: "No pude eliminar la esfera")\n                    _snackbar.value = it.message ?: "No pude eliminar la esfera"\n                }\n        }\n    }\n'''
s=s[:start]+new+s[end:]
